type ONUStatus = "online" | "alerta" | "offline";

type ONU = {
  id: string;
  serial: string;
  mac: string;
  name: string;
  slot: string;
  status: ONUStatus;
  signal: number;
  distance: number;
  uptime: string;
  lastEvent: string;
  profile: string;
};

type TelemetryPoint = { at: number; signal: number; status: ONUStatus; distance: number; event: string };

type EventItem = {
  id: string;
  type: "fiber" | "warning" | "power";
  title: string;
  detail: string;
  time: string;
  fresh?: boolean;
};

