const speedPlans = [200, 400, 600, 800].map((download) => ({ download: `${download}MB-DOWN`, upload: `${download / 2}MB-UP`, label: `${download} Mbps` }));

function formatDistance(distance: number) { return distance <= 0 ? "—" : distance < 1 ? `${Math.round(distance * 1000)} m` : `${distance.toFixed(2)} km`; }

function normalizeSpeed(value: string, suffix: "UP" | "DOWN") {
  const raw = String(value ?? "").trim().replace(new RegExp(`(?:-?${suffix})+$`, "i"), "");
  return raw ? `${raw}-${suffix}` : "";
}

function expandTemplate(body: string, values: Record<string, string | number>) {
  const vlan = String(values.vlan ?? "").trim();
  return body.split(/\r?\n/).map((line) => line.trim()).filter((line) => line && !line.startsWith("#")).map((line) => line.replace(/\{([a-z0-9-]+)\}/gi, (_, key: string) => values[key.toLowerCase()] === undefined ? `{${key}}` : String(values[key.toLowerCase()])).replace(/\buser-vlan\s+vlan\b/gi, `user-vlan ${vlan}`).replace(/\bvlan\s+vlan\b/gi, `vlan ${vlan}`));
}

function statusMeta(status: ONUStatus) {
  if (status === "online") return { label: "Online", dot: "bg-emerald-400", text: "text-emerald-300", bg: "bg-emerald-400/10 border-emerald-400/20" };
  if (status === "alerta") return { label: "Alerta", dot: "bg-amber-300", text: "text-amber-200", bg: "bg-amber-300/10 border-amber-300/20" };
  return { label: "Offline", dot: "bg-rose-400", text: "text-rose-300", bg: "bg-rose-400/10 border-rose-400/20" };
}

function SignalBars({ signal }: { signal: number }) {
  const level = getSignalLevel(signal);
  return (
    <div className="flex items-end gap-0.5 h-4" aria-label={`${signal} dBm`}>
      {[1, 2, 3, 4].map((bar) => <span key={bar} className={`w-1 rounded-sm ${bar <= level ? "bg-fuchsia-300" : "bg-slate-700"}`} style={{ height: `${bar * 3 + 3}px` }} />)}
    </div>
  );
}

function MiniSparkline() {
  const points = signalPoints.map((point, index) => `${(index / (signalPoints.length - 1)) * 100},${100 - point}`).join(" ");
  return (
    <svg viewBox="0 0 100 42" preserveAspectRatio="none" className="h-14 w-full overflow-visible">
      <defs><linearGradient id="spark-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stopColor="#22d3ee" stopOpacity=".28" /><stop offset="100%" stopColor="#22d3ee" stopOpacity="0" /></linearGradient></defs>
      <polyline points={`0,42 ${points} 100,42`} fill="url(#spark-fill)" stroke="none" />
      <polyline points={points} fill="none" stroke="#67e8f9" strokeWidth="1.6" vectorEffect="non-scaling-stroke" />
    </svg>
  );
}

function Badge({ status }: { status: ONUStatus }) {
  const meta = statusMeta(status);
  return <span className={`inline-flex items-center gap-1.5 rounded-full border px-2 py-1 text-[10px] font-semibold uppercase tracking-[.08em] ${meta.bg} ${meta.text}`}><span className={`h-1.5 w-1.5 rounded-full ${meta.dot}`} />{meta.label}</span>;
}

function ActionButton({ icon: Icon, label, tone = "muted", onClick }: { icon: typeof Power; label: string; tone?: "muted" | "danger" | "cyan"; onClick: () => void }) {
  const toneClass = tone === "danger" ? "hover:border-rose-400/40 hover:bg-rose-400/10 hover:text-rose-200" : tone === "cyan" ? "hover:border-fuchsia-300/40 hover:bg-fuchsia-300/10 hover:text-fuchsia-100" : "hover:border-slate-500 hover:bg-slate-800 hover:text-slate-100";
  return <button onClick={onClick} className={`group inline-flex items-center gap-1.5 rounded-lg border border-transparent px-2 py-1.5 text-[11px] font-medium text-slate-400 transition-all ${toneClass}`}><Icon className="h-3.5 w-3.5 transition-transform group-hover:scale-110" />{label}</button>;
}

export default function Home() {
  const { user, loading: authLoading, logout, login, loginPending, loginError } = useAuth();
  const [loginForm, setLoginForm] = useState({ username: "", password: "" });
  const [onus, setOnus] = useState<ONU[]>([]);
  const [events, setEvents] = useState<EventItem[]>(initialEvents);
  const [selectedId, setSelectedId] = useState<string | null>("onu-02");
  const [onuHistory, setOnuHistory] = useState<Record<string, TelemetryPoint[]>>(() => { try { return JSON.parse(localStorage.getItem("olt-onu-history") || "{}") as Record<string, TelemetryPoint[]>; } catch { return {}; } });
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<"todos" | ONUStatus>("todos");
  const [ponFilter, setPonFilter] = useState("todos");
  const [activeNav, setActiveNav] = useState("Visão geral");
  const [templates, setTemplates] = useState(() => { try { const saved = JSON.parse(localStorage.getItem("olt-templates") || "null") as Array<{id:number;name:string;body:string}> | null; return saved?.length ? saved : defaultTemplates; } catch { return defaultTemplates; } });
  const [templateName, setTemplateName] = useState("");
  const [templateBody, setTemplateBody] = useState("");
  const [editingTemplateId, setEditingTemplateId] = useState<number | null>(null);
  const [provisionForm, setProvisionForm] = useState({ onuId: "", pon: "", serial: "", vlan: "", description: "", templateId: "", plan: "", upload: "", download: "", wifiSsid: "", wifiPassword: "" });
  const [moveForm, setMoveForm] = useState({ source: "", targetPon: "", targetOnuId: "", serial: "" });
  const [realtimeEvents, setRealtimeEvents] = useState<EventItem[]>([]);
  const [operationLogs, setOperationLogs] = useState<Array<{id:number;action:string;onu?:string|null;createdAt?:string|Date;operatorName?:string|null;commands?:string[]}>>([]);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [lastSync, setLastSync] = useState(() => new Intl.DateTimeFormat("pt-BR", { timeStyle: "short", timeZone: "America/Sao_Paulo" }).format(new Date()));
  const [cachedSnapshot] = useState(() => { try { return JSON.parse(localStorage.getItem("olt-live-snapshot") || "null"); } catch { return null; } });
  const liveSnapshot = trpc.olt.liveSnapshot.useQuery(undefined, { enabled: Boolean(user), initialData: cachedSnapshot ?? undefined, initialDataUpdatedAt: cachedSnapshot?.syncedAt ?? undefined, refetchInterval: 5000, refetchIntervalInBackground: true, staleTime: 5000, retry: 1 });
  const tableRef = useRef<HTMLDivElement>(null);
  const operatorAction = trpc.olt.operatorAction.useMutation();
  const unconfiguredOnus = trpc.olt.unconfiguredOnus.useQuery(undefined, { enabled: Boolean(user) && (activeNav === "Autorizar ONU" || activeNav === "Adicionar ONU"), refetchInterval: 5000, refetchIntervalInBackground: true });
  const selectedUnconfigured = unconfiguredOnus.data?.find((item) => `${item.pon}:${item.serial}` === provisionForm.onuId);
  const availabilityPon = activeNav === "Adicionar ONU" ? provisionForm.pon : selectedUnconfigured?.pon;
  const ponAvailability = trpc.olt.ponAvailability.useQuery({ pon: availabilityPon ?? "1/8/1" }, { enabled: Boolean(availabilityPon), refetchInterval: 5000 });
  const authorizeUnconfigured = trpc.olt.authorizeUnconfigured.useMutation();
  const moveOnu = trpc.olt.moveOnu.useMutation();
  const moveAvailability = trpc.olt.ponAvailability.useQuery({ pon: moveForm.targetPon || "1/8/1" }, { enabled: activeNav === "Mover ONU" && Boolean(moveForm.targetPon), refetchInterval: 5000 });
  const descriptionUpdate = trpc.olt.updateDescription.useMutation();
  const oltConfig = trpc.olt.config.useQuery();
  const configUpdate = trpc.olt.updateConfig.useMutation();
  const [configForm, setConfigForm] = useState({ host: "", snmpPort: "", telnetPort: "", boards: "", telnetUsername: "", telnetPassword: "" });
  const [oltProfiles, setOltProfiles] = useState(() => { try { return JSON.parse(localStorage.getItem("olt-profiles") || "[]") as Array<{name:string;host:string;snmpPort:string;telnetPort:string;boards:string}>; } catch { return []; } });
  const [oltProfileName, setOltProfileName] = useState("");
  const [logoSrc, setLogoSrc] = useState(() => localStorage.getItem("olt-logo") || "/logo-xtremnet.png");
  const [editingDescriptionId, setEditingDescriptionId] = useState<string | null>(null);
  const [descriptionDraft, setDescriptionDraft] = useState("");
  const [deauthorizeTarget, setDeauthorizeTarget] = useState("");
  const [operatorUsers, setOperatorUsers] = useState<Array<{id:number;name:string;email:string|null;username:string;role:string}>>([]);
  const [editingUserIndex, setEditingUserIndex] = useState<number | null>(null);
  const [newOperator, setNewOperator] = useState({ name: "", email: "", username: "", password: "", role: "tecnico" });
  const [networkEntries, setNetworkEntries] = useState(() => { try { return JSON.parse(localStorage.getItem("olt-network-entries") || "[]") as Array<{name:string;interfaceName:string;vlan:string;ip:string;mask:string;gateway:string}>; } catch { return []; } });
  const [networkForm, setNetworkForm] = useState({ name: "", interfaceName: "", vlan: "", ip: "", mask: "", gateway: "" });
  const [terminalCommand, setTerminalCommand] = useState("show version");
  const [terminalHistory, setTerminalHistory] = useState<Array<{command:string;output:string;time:string}>>([]);
  const networkConfig = trpc.olt.networkConfig.useQuery(undefined, { enabled: Boolean(user) && activeNav === "Interfaces / VLANs", staleTime: 5 * 60 * 1000, refetchInterval: 5 * 60 * 1000, refetchIntervalInBackground: true, refetchOnWindowFocus: false });
  const terminalMutation = trpc.olt.terminal.useMutation();
  const operatorList = trpc.operators.list.useQuery(undefined, { enabled: Boolean(user) && activeNav === "Users", retry: false });
  const operatorSave = trpc.operators.save.useMutation({ onSuccess: () => operatorList.refetch() });
  const operatorRemove = trpc.operators.remove.useMutation({ onSuccess: () => operatorList.refetch() });
  const logsList = trpc.logs.list.useQuery(undefined, { enabled: Boolean(user) && (activeNav === "Logs de operação" || Boolean(selectedId)), retry: false });
  const logCreate = trpc.logs.create.useMutation();

  useEffect(() => { if (operatorList.data) setOperatorUsers(operatorList.data); }, [operatorList.data]);
  useEffect(() => { if (logsList.data) setOperationLogs(logsList.data); }, [logsList.data]);
  useEffect(() => {
    const snapshotOnus = liveSnapshot.data?.onus ?? [];
    if (!snapshotOnus.length) return;
    setOnuHistory((current) => {
      const next = { ...current };
      for (const onu of snapshotOnus) {
        const point: TelemetryPoint = { at: liveSnapshot.data?.syncedAt ?? Date.now(), signal: onu.signal, status: onu.status, distance: onu.distance, event: onu.lastEvent };
        const previous = next[onu.id] ?? [];
        const last = previous[previous.length - 1];
        if (last && Math.abs(last.signal - point.signal) < 0.01 && last.status === point.status && last.event === point.event) continue;
        next[onu.id] = [...previous, point].slice(-120);
      }
      try { localStorage.setItem("olt-onu-history", JSON.stringify(next)); } catch { /* armazenamento local cheio */ }
      return next;
    });
  }, [liveSnapshot.data?.syncedAt]);

  const ponOptions = useMemo(() => {
    const configured = (oltConfig.data?.boards ?? "").split(",").flatMap((entry) => {
      const [slot, countText] = entry.split(":");
      const count = Number(countText);
      return Number.isInteger(count) ? Array.from({ length: count }, (_, index) => `1/${slot}/${index + 1}`) : [];
    });
    return Array.from(new Set([...configured, ...onus.map((onu) => onu.slot.split(":")[0])])).sort();
  }, [oltConfig.data?.boards, onus]);

  const sortedOnus = useMemo(() => [...onus].sort((a, b) => Number(b.status === "offline") - Number(a.status === "offline") || Number(b.status === "alerta") - Number(a.status === "alerta")), [onus]);

  const filteredOnus = useMemo(() => {
    const normalizedSearch = search.trim().toLowerCase();
    return sortedOnus.filter((onu) => {
      const matchesSearch = !normalizedSearch || `${onu.name} ${onu.serial} ${onu.mac} ${onu.slot}`.toLowerCase().includes(normalizedSearch);
      const matchesStatus = statusFilter === "todos" || onu.status === statusFilter;
      const matchesPon = ponFilter === "todos" || onu.slot.startsWith(`${ponFilter}:`);
      return matchesSearch && matchesStatus && matchesPon;
    });
  }, [sortedOnus, search, statusFilter, ponFilter]);
  const selected = onus.find((onu) => onu.id === selectedId) ?? onus[0];
  const selectedHistory = selected ? (onuHistory[selected.id] ?? []) : [];
  const selectedLogs = selected ? operationLogs.filter((log) => log.onu === selected.slot || log.onu?.startsWith(`${selected.slot}:`)) : [];
  const historySignals = selectedHistory.filter((point) => point.signal > -90);
  const minHistorySignal = historySignals.length ? Math.min(...historySignals.map((point) => point.signal)) : 0;
  const maxHistorySignal = historySignals.length ? Math.max(...historySignals.map((point) => point.signal)) : 0;
  const onlineCount = onus.filter((onu) => onu.status === "online").length;
  const alertCount = onus.filter((onu) => onu.status === "alerta").length;
  const offlineCount = onus.filter((onu) => onu.status === "offline").length;
  const onlineOnus = onus.filter((onu) => onu.status === "online" || onu.status === "alerta");
  const moveSource = onus.find((onu) => onu.slot === moveForm.source);
  const deauthorizeSource = onus.find((onu) => onu.slot === deauthorizeTarget);
  function refreshAfterMutation() { liveSnapshot.refetch(); window.setTimeout(() => liveSnapshot.refetch(), 500); window.setTimeout(() => liveSnapshot.refetch(), 1500); window.setTimeout(() => liveSnapshot.refetch(), 3500); }

  function authorizationScript() {
    const manual = activeNav === "Adicionar ONU";
    const pon = manual ? provisionForm.pon : selectedUnconfigured?.pon;
    const targetSerial = manual ? provisionForm.serial.trim() : selectedUnconfigured?.serial ?? provisionForm.serial.trim();
    const onuId = ponAvailability.data?.nextOnuId ?? "{onu-id}";
    if (!pon || !targetSerial) return "configure terminal\n! Preencha a PON e o SN da ONU";
    const template = templates.find((item) => String(item.id) === provisionForm.templateId);
    const [slot, ponNumber] = pon.split("/").slice(1);
    const commands = template ? expandTemplate(template.body, { vlan: provisionForm.vlan, "onu-id": onuId, slot: slot ?? "", pon: ponNumber ?? "", "pon-path": pon, sn: targetSerial, description: provisionForm.description, upload: normalizeSpeed(provisionForm.upload, "UP"), download: normalizeSpeed(provisionForm.download, "DOWN"), "wifi-ssid": provisionForm.wifiSsid, "wifi-password": provisionForm.wifiPassword }) : [`interface gpon-olt_${pon}`, `onu ${onuId} type ZTE-F680 sn ${targetSerial}`, "exit", `interface gpon-onu_${pon}:${onuId}`, ...(provisionForm.description ? [`description ${provisionForm.description}`] : [])];
    return ["terminal length 0", "configure terminal", ...commands, "end", "write"].join("\n");
  }

  async function copyAuthorizationScript() {
    try { await navigator.clipboard.writeText(authorizationScript()); toast.success("Script de autorização copiado"); }
    catch { toast.error("Não foi possível copiar o script", { description: "Selecione e copie o preview manualmente." }); }
  }

  function authorizeDiscovered() {
    const manual = activeNav === "Adicionar ONU";
    const pon = manual ? provisionForm.pon : selectedUnconfigured?.pon;
    const serial = provisionForm.serial.trim();
    if (manual && (!pon || !serial)) { toast.warning("Informe a PON e o SN da ONU"); return; }
    if (!manual && !selectedUnconfigured) { toast.warning("Selecione uma ONU não configurada"); return; }
    if (!pon || !ponAvailability.data?.nextOnuId) { toast.warning("Aguarde o cálculo da primeira vaga livre"); return; }
    const targetSerial = manual ? serial : selectedUnconfigured!.serial;
    const template = templates.find((item) => String(item.id) === provisionForm.templateId);
    const [slot, ponNumber] = pon.split("/").slice(1);
    const commands = template ? expandTemplate(template.body, { vlan: provisionForm.vlan, "onu-id": ponAvailability.data.nextOnuId, slot: slot ?? "", pon: ponNumber ?? "", "pon-path": pon ?? "", sn: targetSerial, description: provisionForm.description, upload: normalizeSpeed(provisionForm.upload, "UP"), download: normalizeSpeed(provisionForm.download, "DOWN"), "wifi-ssid": provisionForm.wifiSsid, "wifi-password": provisionForm.wifiPassword }) : [];
    const needsVlan = Boolean(template && /\b(?:user-vlan|vlan)\s+(?:vlan|\{vlan\})\b/i.test(template.body));
    if (needsVlan && !/^\d{1,4}$/.test(provisionForm.vlan.trim())) { toast.warning("Informe uma VLAN numérica antes de autorizar"); return; }
    if (commands.some((command) => /\{[a-z0-9-]+\}/i.test(command) || /\b(?:user-vlan|vlan)\s+vlan\b/i.test(command))) { toast.warning("Preencha corretamente todas as variáveis do template"); return; }
    const preview = authorizationScript();
    if (!window.confirm(`PRÉVIA — comandos que serão enviados à OLT\n\nAutorizar ${targetSerial} na PON ${pon}, vaga ${ponAvailability.data.nextOnuId}?\n\nTemplate: ${template?.name ?? "sem template"}\n\n${preview}\n\nClique em OK para executar ou Cancelar para não enviar nada.`)) return;
    toast("Enviando comandos para a OLT", { description: commands.slice(0, 3).join(" → ") + (commands.length > 3 ? ` · +${commands.length - 3} comandos` : "") });
    authorizeUnconfigured.mutate({ pon, serial: targetSerial, onuId: ponAvailability.data.nextOnuId, description: provisionForm.description || undefined, commands }, { onSuccess: async () => { const target = `${pon}:${ponAvailability.data?.nextOnuId}`; toast.success("ONU autorizada", { description: `${target} · coleta iniciada` }); logCreate.mutate({ action: "autorizar", onu: target, commands }); await Promise.all([liveSnapshot.refetch(), unconfiguredOnus.refetch()]); refreshAfterMutation(); window.setTimeout(() => unconfiguredOnus.refetch(), 1500); }, onError: (error) => toast.error("Falha ao autorizar ONU", { description: error.message }) });
  }

  function moveSelected() {
    if (!moveSource || !/^\d+\/\d+\/\d+$/.test(moveForm.targetPon) || !moveAvailability.data?.nextOnuId) { toast.warning("Informe ONU e PON destino; aguarde o cálculo da vaga livre"); return; }
    const sourcePon = moveSource.slot.split(":")[0];
    const sourceId = moveSource.slot.split(":")[1];
    const targetId = moveAvailability.data.nextOnuId;
    const moveCommands = ["terminal length 0", `show running-config interface gpon-onu_${moveSource.slot}`, "configure terminal", `interface gpon-olt_${sourcePon}`, `no onu ${sourceId}`, `interface gpon-olt_${moveForm.targetPon}`, `onu ${targetId} type ZTE-F680 sn ${moveForm.serial || moveSource.serial}`, "exit", `interface gpon-onu_${moveForm.targetPon}:${targetId}`, "[reaplicar configuração da interface de origem]", "end"];
    if (!window.confirm(`PRÉVIA — comandos que serão enviados à OLT\n\nMover ${moveSource.slot} para ${moveForm.targetPon}:${targetId}?\n\n${moveCommands.join("\n")}\n\nA configuração da interface de origem será reaplicada automaticamente.\n\nClique em OK para executar ou Cancelar para não enviar nada.`)) return;
    toast("Enviando comandos de movimentação", { description: moveCommands.slice(0, 4).join(" → ") + " · configuração será reaplicada" });
    moveOnu.mutate({ source: moveSource.slot, targetPon: moveForm.targetPon, targetOnuId: moveAvailability.data.nextOnuId, serial: moveForm.serial || moveSource.serial }, { onSuccess: async () => { const target = `${moveForm.targetPon}:${moveAvailability.data?.nextOnuId}`; logCreate.mutate({ action: "mover", onu: moveSource.slot, commands: moveCommands }); toast.success("ONU movida", { description: target }); await liveSnapshot.refetch(); setActiveNav("ONUs / Clientes"); }, onError: (error) => toast.error("Falha ao mover ONU", { description: error.message }) });
  }

  function saveTemplate() {
    const name = templateName.trim();
    if (!name || !templateBody.trim()) { toast.warning("Informe nome e texto do template"); return; }
    const item = { id: editingTemplateId ?? Date.now(), name, body: templateBody.trim() };
    const next = editingTemplateId === null ? [...templates, item] : templates.map((current) => current.id === editingTemplateId ? item : current);
    setTemplates(next); localStorage.setItem("olt-templates", JSON.stringify(next)); setTemplateName(""); setTemplateBody(""); setEditingTemplateId(null); toast.success(editingTemplateId === null ? "Template salvo localmente" : "Template atualizado");
  }
  function editTemplate(item: { id: number; name: string; body: string }) { setEditingTemplateId(item.id); setTemplateName(item.name); setTemplateBody(item.body); }
  function deleteTemplate(id: number) { const next = templates.filter((item) => item.id !== id); setTemplates(next); localStorage.setItem("olt-templates", JSON.stringify(next)); if (editingTemplateId === id) { setEditingTemplateId(null); setTemplateName(""); setTemplateBody(""); } }
  async function copyTemplate(text: string) { try { await navigator.clipboard.writeText(text); toast.success("Comandos copiados"); } catch { toast.error("Não foi possível copiar", { description: "Copie o texto manualmente." }); } }

  function navigate(label: string) {
    setActiveNav(label);
    setSidebarOpen(false);
    if (label === "ONUs / Clientes") {
      focusTable("todos");
    } else if (label === "Visão geral") {
      window.scrollTo({ top: 0, behavior: "smooth" });
    } else if (label === "Diagnóstico") {
      toast("Diagnóstico da OLT", { description: liveSnapshot.data ? `${liveSnapshot.data.hostname} · ${liveSnapshot.data.onus.length} ONUs lidas` : "Aguardando telemetria" });
    } else if (label === "Eventos de fibra") {
      toast("Eventos de fibra", { description: `${events.length} eventos no feed operacional` });
    } else if (label === "Logs de operação") {
      toast("Logs de operação", { description: "Os comandos executados nesta sessão aparecem aqui." });
    } else if (label === "Templates") { window.scrollTo({ top: 0, behavior: "smooth" }); } else if (label === "Autorizar ONU") { window.scrollTo({ top: 0, behavior: "smooth" }); } else if (label === "Mover ONU") { window.scrollTo({ top: 0, behavior: "smooth" }); } else if (label === "Tempo real") { window.scrollTo({ top: 0, behavior: "smooth" }); } else if (label === "Adicionar ONU") { window.scrollTo({ top: 0, behavior: "smooth" }); } else if (label === "Configurações") {
      toast("Configurações", { description: "Parâmetros da ZTE C300" });
    }
  }

  function focusTable(filter: "todos" | ONUStatus) {
    setStatusFilter(filter);
    setActiveNav("ONUs / Clientes");
    window.setTimeout(() => tableRef.current?.scrollIntoView({ behavior: "smooth", block: "start" }), 20);
  }

  useEffect(() => {
    if (oltConfig.data) setConfigForm((current) => ({ ...current, host: oltConfig.data.host, snmpPort: String(oltConfig.data.snmpPort), telnetPort: String(oltConfig.data.telnetPort), boards: oltConfig.data.boards }));
  }, [oltConfig.data]);

  function saveConfig() {
    configUpdate.mutate({ host: configForm.host.trim(), snmpPort: Number(configForm.snmpPort), telnetPort: Number(configForm.telnetPort), boards: configForm.boards.trim(), telnetUsername: configForm.telnetUsername.trim() || undefined, telnetPassword: configForm.telnetPassword || undefined }, {
      onSuccess: () => { toast.success("Configuração salva", { description: "A próxima sincronização usará os novos parâmetros." }); liveSnapshot.refetch(); oltConfig.refetch(); },
      onError: (error) => toast.error("Configuração inválida", { description: error.message }),
    });
  }

  useEffect(() => {
    if (!liveSnapshot.data?.onus?.length) return;
    setRealtimeEvents((previous) => {
      const previousById = new Map(previous.map((event) => [event.detail.split(" · ")[0], event]));
      const currentOffline = liveSnapshot.data!.onus.filter((onu) => onu.status === "offline");
      const fresh = currentOffline.filter((onu) => !previousById.has(onu.slot)).map((onu) => ({ id: `${onu.slot}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, type: "fiber" as const, title: "Desconexão de fibra detectada", detail: `${onu.slot} · ${onu.name}`, time: "agora", fresh: true }));
      return [...fresh, ...previous].slice(0, 30);
    });
  }, [liveSnapshot.data?.syncedAt]);

  useEffect(() => {
    if (liveSnapshot.data) {
      localStorage.setItem("olt-live-snapshot", JSON.stringify(liveSnapshot.data));
      setOnus(liveSnapshot.data.onus ?? []);
      setLastSync(new Intl.DateTimeFormat("pt-BR", { timeStyle: "short", timeZone: "America/Sao_Paulo" }).format(new Date(liveSnapshot.data.syncedAt ?? Date.now())));
    }
  }, [liveSnapshot.data]);

  function runAction(action: string, onu: ONU) {
    if (liveSnapshot.isLoading) {
      toast.warning("Aguarde a conexão", { description: "A telemetria real ainda está sincronizando com a OLT." });
      return;
    }
    const labels: Record<string, string> = { authorize: "ativar", disable: "desativar", deauthorize: "desautorizar e remover", reboot: "reiniciar" };
    const commands = action === "reboot" ? ["terminal length 0", "configure terminal", `pon-onu-mng gpon-onu_${onu.slot}`, "reboot", "yes", "end"] : action === "deauthorize" ? ["terminal length 0", "configure terminal", `interface gpon-olt_${onu.slot.split(":")[0]}`, `no onu ${onu.slot.split(":")[1]}`, "end"] : ["terminal length 0", "configure terminal", `interface gpon-onu_${onu.slot}`, action === "disable" ? "disable" : "enable", "end"];
    if (!window.confirm(`PRÉVIA — comandos que serão enviados à OLT\n\nAção: ${labels[action] ?? action} · ONU: ${onu.slot}\n\n${commands.join("\n")}\n\nClique em OK para executar ou Cancelar para não enviar nada.`)) return;
    toast("Enviando comando para a OLT", { description: commands.join(" → ") });
    if (action === "deauthorize") setOnus((current) => current.filter((item) => item.id !== onu.id));
    else if (action === "disable") setOnus((current) => current.map((item) => item.id === onu.id ? { ...item, status: "offline", lastEvent: "Desativada pelo operador" } : item));
    else if (action === "authorize") setOnus((current) => current.map((item) => item.id === onu.id ? { ...item, status: "online", lastEvent: "Ativada pelo operador" } : item));
    else if (action === "reboot") setOnus((current) => current.map((item) => item.id === onu.id ? { ...item, lastEvent: "Reboot enviado pelo operador" } : item));
    operatorAction.mutate({ action: action as "authorize" | "disable" | "deauthorize" | "reboot", onuId: onu.slot }, {
      onSuccess: async () => {
        toast.success(`Comando executado: ${labels[action] ?? action}`, { description: `${onu.name} · ${onu.slot}` });
        logCreate.mutate({ action: labels[action] ?? action, onu: onu.slot, commands });
        refreshAfterMutation();
      },
      onError: (error) => toast.error("Comando não executado", { description: error.message }),
    });
  }

  function startDescriptionEdit(onu: ONU) {
    setEditingDescriptionId(onu.id);
    setDescriptionDraft(onu.name.startsWith("ONU ") ? "" : onu.name);
  }

  function saveDescription(onu: ONU) {
    const description = descriptionDraft.trim();
    if (!description) { toast.warning("Digite uma descrição"); return; }
    if (!window.confirm(`Alterar a descrição da ONU ${onu.slot} para:\n\n${description}\n\nA alteração será aplicada na OLT ZTE C300 agora.`)) return;
    toast("Enviando comando para a OLT", { description: `configure terminal → interface gpon-onu_${onu.slot} → name ${description}` });
    descriptionUpdate.mutate({ onuId: onu.slot, description }, {
      onSuccess: async () => {
        setOnus((current) => current.map((item) => item.id === onu.id ? { ...item, name: description } : item));
        setEditingDescriptionId(null);
        toast.success("Descrição alterada na OLT", { description: `${onu.slot} · ${description}` });
        logCreate.mutate({ action: "editar descrição", onu: onu.slot, commands: ["configure terminal", `interface gpon-onu_${onu.slot}`, `name ${description}`, "end", "write"] });
        await liveSnapshot.refetch();
      },
      onError: (error) => toast.error("Não foi possível alterar a descrição", { description: error.message }),
    });
  }

  function addFiberEvent() {
    const target = onus.find((onu) => onu.status === "online") ?? onus[0];
    if (!target) {
      toast.warning("Aguardando dados reais", { description: "A OLT ainda não retornou nenhuma ONU." });
      return;
    }
    const event: EventItem = { id: `${target.slot}-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`, type: "fiber", title: "Teste de desconexão recebido", detail: `${target.slot} · ${target.name}`, time: "agora", fresh: true };
    setEvents((current) => [event, ...current].slice(0, 5));
    toast.warning("Eventos são somente da telemetria real", { description: "Nenhum evento manual é inserido no feed." });
  }

  if (authLoading) return <div className="flex min-h-screen items-center justify-center bg-[#121126] text-sm text-slate-300">Carregando autenticação...</div>;
  if (!user) return <div className="flex min-h-screen items-center justify-center bg-[#121126] p-6"><form onSubmit={(event) => { event.preventDefault(); login(loginForm.username, loginForm.password).catch(() => undefined); }} className="w-full max-w-md rounded-2xl border border-fuchsia-300/20 bg-[#0b1a2a] p-8 shadow-2xl"><img src={logoSrc} alt="XtremNet" className="mx-auto mb-6 h-16 w-auto object-contain" /><h1 className="text-center text-2xl font-semibold text-white">Acesso ao OLT.OPS</h1><p className="mt-2 text-center text-sm text-slate-400">Entre com seu usuário e senha para acessar a operação.</p><label className="mt-6 block text-left text-xs font-semibold uppercase tracking-wider text-slate-400">Usuário<input autoFocus value={loginForm.username} onChange={(event) => setLoginForm({ ...loginForm, username: event.target.value })} autoComplete="username" className="mt-2 h-11 w-full rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-sm text-white outline-none focus:border-fuchsia-300" /></label><label className="mt-4 block text-left text-xs font-semibold uppercase tracking-wider text-slate-400">Senha<input type="password" value={loginForm.password} onChange={(event) => setLoginForm({ ...loginForm, password: event.target.value })} autoComplete="current-password" className="mt-2 h-11 w-full rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-sm text-white outline-none focus:border-fuchsia-300" /></label>{loginError && <p className="mt-3 rounded-lg border border-rose-400/30 bg-rose-400/10 px-3 py-2 text-sm text-rose-200">{loginError.message || "Usuário ou senha inválidos."}</p>}<button disabled={loginPending || !loginForm.username || !loginForm.password} className="mt-6 w-full rounded-lg bg-fuchsia-300 px-4 py-3 text-sm font-bold text-slate-950 transition hover:bg-fuchsia-200 disabled:cursor-not-allowed disabled:opacity-50">{loginPending ? "Entrando..." : "Entrar"}</button></form></div>;

  return (
    <div className="min-h-screen bg-[#07111e] text-slate-100 selection:bg-fuchsia-300/20">
      <div className="pointer-events-none fixed inset-0 bg-[radial-gradient(circle_at_80%_0%,rgba(14,116,144,.12),transparent_32%),radial-gradient(circle_at_0%_100%,rgba(30,64,175,.1),transparent_38%)]" />
      <div className="relative flex min-h-screen">
        {sidebarOpen && <button className="fixed inset-0 z-30 bg-black/60 lg:hidden" onClick={() => setSidebarOpen(false)} aria-label="Fechar menu" />}
        <aside className={`fixed inset-y-0 left-0 z-40 flex w-[246px] flex-col border-r border-slate-800/80 bg-[#091522]/95 px-4 py-5 backdrop-blur-xl transition-transform lg:static lg:translate-x-0 ${sidebarOpen ? "translate-x-0" : "-translate-x-full"}`}>
          <div className="flex items-center justify-between px-2">
            <div className="flex items-center gap-3"><div className="flex h-10 w-28 items-center justify-center overflow-hidden rounded-lg border border-fuchsia-300/20 bg-white px-1"><img src={logoSrc} alt="XtremNet" className="h-full w-full object-contain" /></div><div><p className="text-sm font-bold tracking-wide text-white">OLT<span className="text-fuchsia-300">.OPS</span></p><p className="text-[10px] uppercase tracking-[.16em] text-slate-500">XtremNet · ZTE command center</p></div></div>
            <button className="text-slate-500 lg:hidden" onClick={() => setSidebarOpen(false)}><X className="h-5 w-5" /></button>
          </div>
          <div className="mt-8 rounded-xl border border-fuchsia-300/15 bg-fuchsia-300/[.06] p-3"><div className="flex items-center justify-between"><div className="flex items-center gap-2"><span className={`relative flex h-2.5 w-2.5 ${liveSnapshot.isError ? "bg-rose-400" : ""}`}><span className={`absolute inline-flex h-full w-full animate-ping rounded-full opacity-60 ${liveSnapshot.isError ? "bg-rose-400" : "bg-emerald-400"}`} /><span className={`relative inline-flex h-2.5 w-2.5 rounded-full ${liveSnapshot.isError ? "bg-rose-400" : "bg-emerald-400"}`} /></span><span className={`text-xs font-semibold ${liveSnapshot.isError ? "text-rose-200" : "text-emerald-200"}`}>{liveSnapshot.isError ? "Sem resposta" : "Conectada"}</span></div></div><p className="mt-2 text-xs text-slate-400">{liveSnapshot.data?.model ?? "ZTE C300"} · {liveSnapshot.data?.host ?? "45.162.123.46"}</p><div className="mt-3 flex items-center justify-between text-[10px] text-slate-500"><span>Hostname</span><span className="max-w-[125px] truncate font-mono text-slate-300">{liveSnapshot.data?.hostname ?? "aguardando..."}</span></div></div>
          <nav className="mt-8 space-y-1"><p className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-slate-600">Operação</p>{[{ label: "Visão geral", icon: LayoutDashboard }, { label: "ONUs / Clientes", icon: Network }, { label: "Eventos de fibra", icon: Cable }, { label: "Diagnóstico", icon: Activity }].map(({ label, icon: Icon }) => <button key={label} onClick={() => navigate(label)} className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm transition-colors ${activeNav === label ? "bg-fuchsia-300/10 text-fuchsia-100 shadow-[inset_2px_0_0_#67e8f9]" : "text-slate-400 hover:bg-slate-800/70 hover:text-slate-200"}`}><Icon className="h-4 w-4" /><span>{label}</span>{label === "Eventos de fibra" && <span className="ml-auto rounded-full bg-rose-400/15 px-1.5 py-0.5 text-[10px] text-rose-300">3</span>}</button>)}</nav>
          <nav className="mt-8 space-y-1"><p className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-slate-600">Operações</p>{[{ label: "Autorizar ONU", icon: ShieldCheck }, { label: "Desautorizar ONU", icon: LockKeyhole }, { label: "Adicionar ONU", icon: Plus }, { label: "Mover ONU", icon: MoveRight }, { label: "Tempo real", icon: WifiOff }, { label: "Templates", icon: FileText }, { label: "Logs de operação", icon: ClipboardList }, { label: "Users", icon: UserRound }, { label: "Interfaces / VLANs", icon: Router }, { label: "Terminal", icon: Terminal }, { label: "Configurações", icon: Settings2 }].map(({ label, icon: Icon }) => <button key={label} onClick={() => navigate(label)} className={`flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-left text-sm transition-colors ${activeNav === label ? "bg-slate-800 text-slate-100" : "text-slate-400 hover:bg-slate-800/70 hover:text-slate-200"}`}><Icon className="h-4 w-4" /><span>{label}</span></button>)}</nav>
          <div className="mt-auto space-y-3"><button onClick={() => toast("Central de suporte", { description: "A equipe de NOC está disponível para apoiar sua operação." })} className="flex w-full items-center gap-3 rounded-lg px-3 py-2 text-sm text-slate-500 transition-colors hover:bg-slate-800/70 hover:text-slate-300"><LifeBuoy className="h-4 w-4" />Central de suporte</button><div className="flex items-center gap-3 border-t border-slate-800/80 px-2 pt-4"><div className="flex h-8 w-8 items-center justify-center rounded-full bg-slate-700 text-xs font-bold text-slate-200">AC</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-semibold text-slate-200">{user?.name || "Operador"}</p><p className="truncate text-[10px] text-slate-500">{user?.email || "Operador NOC"}</p></div><MoreHorizontal className="h-4 w-4 text-slate-600" /></div></div>
        </aside>

        <main className="min-w-0 flex-1">
          <header className="flex h-[72px] items-center justify-between border-b border-slate-800/80 px-5 sm:px-8"><div className="flex items-center gap-3"><button className="rounded-lg p-2 text-slate-400 hover:bg-slate-800 lg:hidden" onClick={() => setSidebarOpen(true)}><Menu className="h-5 w-5" /></button><div><div className="flex items-center gap-2"><span className="text-xs font-semibold uppercase tracking-[.15em] text-fuchsia-300">Monitoramento</span></div><h1 className="mt-1 text-lg font-semibold tracking-tight text-white">Visão geral da OLT</h1></div></div><div className="flex items-center gap-3"><div className="hidden items-center gap-2 text-[11px] text-slate-500 sm:flex"><span className="h-1.5 w-1.5 rounded-full bg-emerald-400" />Dados atualizados {lastSync}</div><button onClick={() => { setLastSync("sincronizando..."); liveSnapshot.refetch().then(() => { setLastSync("agora"); toast.success("Telemetria sincronizada com a OLT"); }).catch(() => toast.error("Falha ao sincronizar a OLT")); }} className="rounded-lg border border-slate-700 bg-slate-900/60 p-2 text-slate-400 transition hover:border-fuchsia-300/30 hover:text-fuchsia-200"><RefreshCw className="h-4 w-4" /></button><button onClick={() => logout().catch(() => toast.error("Não foi possível sair"))} aria-label="Sair" className="flex h-9 w-9 items-center justify-center rounded-full border border-slate-700 bg-slate-800 text-slate-400"><UserRound className="h-4 w-4" /></button></div></header>

          <div className="mx-auto max-w-[1450px] p-5 sm:p-8">
            {activeNav === "Templates" && <section className="mb-7 rounded-2xl border border-violet-300/20 bg-[#0b1a2a]/90 p-6"><p className="text-xs font-semibold uppercase tracking-[.15em] text-violet-300">Templates</p><h2 className="mt-2 text-xl font-semibold text-white">Textos de configuração reutilizáveis</h2><p className="mt-1 text-xs text-slate-500">Edite qualquer template, copie os comandos e use as variáveis. Velocidades são normalizadas para o formato ZTE, sem repetir -UP ou -DOWN.</p><div className="mt-5 grid gap-3 md:grid-cols-[220px_1fr_auto]"><input value={templateName} onChange={(e) => setTemplateName(e.target.value)} placeholder="Nome do template" className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200" /><textarea value={templateBody} onChange={(e) => setTemplateBody(e.target.value)} placeholder="Cole o texto limpo do template..." className="min-h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 py-2 text-xs text-slate-200" /><button onClick={saveTemplate} className="inline-flex h-10 items-center justify-center gap-2 rounded-lg bg-violet-300 px-4 text-xs font-bold text-slate-950"><Save className="h-4 w-4" />{editingTemplateId === null ? "Adicionar" : "Salvar edição"}</button></div><div className="mt-5 space-y-2">{templates.length === 0 && <p className="text-xs text-slate-500">Nenhum template cadastrado.</p>}{templates.map((item) => <div key={item.id} className="rounded-lg border border-slate-800 bg-slate-950/40 p-3"><div className="flex items-start justify-between gap-3"><p className="text-xs font-semibold text-slate-200">{item.name}</p><div className="flex gap-3"><button onClick={() => editTemplate(item)} className="text-fuchsia-300" title="Editar template"><Pencil className="h-4 w-4" /></button><button onClick={() => copyTemplate(item.body)} className="text-violet-300" title="Copiar template"><Copy className="h-4 w-4" /></button><button onClick={() => deleteTemplate(item.id)} className="text-rose-300" title="Excluir template"><Trash2 className="h-4 w-4" /></button></div></div><pre className="mt-2 whitespace-pre-wrap text-[11px] text-slate-400">{item.body}</pre></div>)}</div></section>}

            {(activeNav === "Autorizar ONU" || activeNav === "Adicionar ONU") && <section className="mb-7 rounded-2xl border border-emerald-300/20 bg-[#0b1a2a]/90 p-6"><p className="text-xs font-semibold uppercase tracking-[.15em] text-emerald-300">{activeNav === "Adicionar ONU" ? "Adicionar ONU" : "Autorizar ONU"}</p><h2 className="mt-2 text-xl font-semibold text-white">{activeNav === "Adicionar ONU" ? "Autorização manual" : "ONUs disponíveis para autorização"}</h2><p className="mt-1 text-xs text-slate-500">Preencha os parâmetros e confirme antes de executar a autorização na OLT.</p><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{activeNav === "Autorizar ONU" ? <select value={provisionForm.onuId} onChange={(e) => { const value = e.target.value; const found = (unconfiguredOnus.data ?? []).find((item) => `${item.pon}:${item.serial}` === value); setProvisionForm({ ...provisionForm, onuId: value, pon: found?.pon ?? "", serial: found?.serial ?? "" }); }} className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200"><option value="">Selecione uma ONU não configurada</option>{(unconfiguredOnus.data ?? []).map((onu) => <option key={`${onu.pon}:${onu.serial}`} value={`${onu.pon}:${onu.serial}`}>{onu.pon} · {onu.serial} · {onu.state}</option>)}</select> : <select value={provisionForm.pon} onChange={(e) => setProvisionForm({ ...provisionForm, pon: e.target.value })} className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200"><option value="">Selecione a PON</option>{ponOptions.map((pon) => <option key={pon} value={pon}>{pon}</option>)}</select>}<input value={provisionForm.serial} onChange={(e) => setProvisionForm({ ...provisionForm, serial: e.target.value })} placeholder="SN da ONU" className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200" /><input value={provisionForm.vlan} onChange={(e) => setProvisionForm({ ...provisionForm, vlan: e.target.value })} placeholder="VLAN" className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200" /><input value={provisionForm.description} onChange={(e) => setProvisionForm({ ...provisionForm, description: e.target.value })} placeholder="Descrição do cliente" className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200" /><select value={provisionForm.templateId} onChange={(e) => setProvisionForm({ ...provisionForm, templateId: e.target.value })} className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200"><option value="">Sem template</option>{templates.map((item) => <option key={item.id} value={String(item.id)}>{item.name}</option>)}</select><div className="sm:col-span-2 lg:col-span-3"><p className="mb-2 text-[10px] font-semibold uppercase tracking-[.14em] text-fuchsia-200/80">Plano e velocidade</p><div className="grid grid-cols-2 gap-2 sm:grid-cols-4">{speedPlans.map((item) => { const selected = provisionForm.plan === item.download; return <button key={item.download} type="button" onClick={() => setProvisionForm({ ...provisionForm, plan: item.download, download: item.download, upload: item.upload })} className={`rounded-xl border px-3 py-3 text-left transition focus:outline-none focus:ring-2 focus:ring-fuchsia-300/40 ${selected ? "border-fuchsia-200 bg-fuchsia-300 text-slate-950 shadow-[0_0_18px_rgba(232,121,249,.22)]" : "border-slate-700 bg-slate-950/80 text-slate-100 hover:border-fuchsia-300/60 hover:bg-slate-900"}`}><span className="block text-sm font-bold">{item.label}</span><span className={`mt-1 block text-[10px] font-medium ${selected ? "text-slate-800" : "text-slate-400"}`}>{item.download} ↓</span><span className={`block text-[10px] font-medium ${selected ? "text-slate-800" : "text-cyan-300"}`}>{item.upload} ↑</span></button>; })}</div></div><div className="flex h-10 items-center justify-between rounded-lg border border-cyan-300/35 bg-slate-900 px-3 text-xs font-semibold text-cyan-100" aria-label="Upload automático"><span className="text-[10px] uppercase tracking-wider text-cyan-300/70">Upload</span><span>{provisionForm.upload || "Selecione o plano"}</span></div><div className="flex h-10 items-center justify-between rounded-lg border border-violet-300/40 bg-slate-900 px-3 text-xs font-semibold text-violet-100" aria-label="Download automático"><span className="text-[10px] uppercase tracking-wider text-violet-300/70">Download</span><span>{provisionForm.download || "Selecione o plano"}</span></div>{templates.find((item) => String(item.id) === provisionForm.templateId)?.name.includes("OMCI") && <><input value={provisionForm.wifiSsid} onChange={(e) => setProvisionForm({ ...provisionForm, wifiSsid: e.target.value })} placeholder="Wi‑Fi SSID (OMCI)" className="h-10 rounded-lg border border-fuchsia-300/20 bg-fuchsia-300/[.06] px-3 text-xs text-slate-200" /><input type="password" value={provisionForm.wifiPassword} onChange={(e) => setProvisionForm({ ...provisionForm, wifiPassword: e.target.value })} placeholder="Senha Wi‑Fi (OMCI)" className="h-10 rounded-lg border border-fuchsia-300/20 bg-fuchsia-300/[.06] px-3 text-xs text-slate-200" /></>}</div><div className="mt-4 text-xs text-slate-500">{activeNav === "Autorizar ONU" ? (unconfiguredOnus.isLoading ? "Consultando show gpon onu uncfg..." : `ONUs não configuradas: ${unconfiguredOnus.data?.length ?? 0}`) : "Cadastro manual: nenhum campo será preenchido automaticamente"}{provisionForm.templateId && <><pre className="mt-2 max-h-96 min-h-48 overflow-auto whitespace-pre rounded-lg border border-violet-300/15 bg-slate-950/50 p-3 font-mono text-[11px] leading-relaxed text-violet-200">{expandTemplate(templates.find((item) => String(item.id) === provisionForm.templateId)?.body ?? "", { vlan: provisionForm.vlan || "{vlan}", "onu-id": ponAvailability.data?.nextOnuId ?? "{onu-id}", slot: provisionForm.pon.split("/")[1] || "{slot}", pon: provisionForm.pon.split("/")[2] || "{pon}", sn: provisionForm.serial || "{sn}", description: provisionForm.description || "{description}", upload: normalizeSpeed(provisionForm.upload, "UP") || "{upload}", download: normalizeSpeed(provisionForm.download, "DOWN") || "{download}", "pon-path": provisionForm.pon || "{pon-path}", "wifi-ssid": provisionForm.wifiSsid || "{wifi-ssid}", "wifi-password": provisionForm.wifiPassword || "{wifi-password}"}).join("\n")}</pre><button onClick={copyAuthorizationScript} className="mt-2 inline-flex items-center gap-2 rounded-lg border border-fuchsia-300/20 px-3 py-2 text-[11px] font-semibold text-fuchsia-200 hover:bg-fuchsia-300/10"><Copy className="h-3.5 w-3.5" />Copiar script completo</button></>}{availabilityPon && <span className="ml-3 text-fuchsia-200">Vaga livre na PON {availabilityPon}: {ponAvailability.isLoading ? "consultando..." : ponAvailability.data?.nextOnuId ?? "sem vaga"}</span>}</div><button onClick={authorizeDiscovered} disabled={authorizeUnconfigured.isPending} className="mt-5 inline-flex items-center gap-2 rounded-lg bg-emerald-300 px-4 py-2.5 text-xs font-bold text-slate-950 disabled:opacity-50"><ShieldCheck className="h-4 w-4" />{authorizeUnconfigured.isPending ? "Autorizando..." : "Autorizar na OLT"}</button></section>}

            {activeNav === "Desautorizar ONU" && <section className="mb-7 rounded-2xl border border-rose-300/20 bg-[#0b1a2a]/90 p-6"><p className="text-xs font-semibold uppercase tracking-[.15em] text-rose-300">Desautorizar ONU</p><h2 className="mt-2 text-xl font-semibold text-white">Remover cadastro da OLT</h2><p className="mt-1 text-xs text-slate-500">Executa em conf t: interface gpon-olt_PON → no onu ID. A ONU será removida da dashboard após a próxima coleta real.</p><div className="mt-5 flex flex-wrap gap-3"><select value={deauthorizeTarget} onChange={(e) => setDeauthorizeTarget(e.target.value)} className="h-10 min-w-[280px] rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200"><option value="">Selecione a ONU</option>{onus.map((onu) => <option key={onu.id} value={onu.slot}>{onu.slot} · {onu.name}</option>)}</select><button onClick={() => deauthorizeSource && runAction("deauthorize", deauthorizeSource)} disabled={!deauthorizeSource || operatorAction.isPending} className="rounded-lg bg-rose-300 px-4 py-2.5 text-xs font-bold text-slate-950 disabled:opacity-50">{operatorAction.isPending ? "Executando..." : "Desautorizar e remover"}</button></div></section>}

            {activeNav === "Mover ONU" && <section className="mb-7 rounded-2xl border border-orange-300/20 bg-[#0b1a2a]/90 p-6"><p className="text-xs font-semibold uppercase tracking-[.15em] text-orange-300">Mover ONU</p><h2 className="mt-2 text-xl font-semibold text-white">Mover ONU para outra PON</h2><p className="mt-1 text-xs text-slate-500">A operação remove a ONU da PON atual e cria o cadastro na PON destino.</p><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><select value={moveForm.source} onChange={(e) => { const source = e.target.value; const found = onus.find((item) => item.slot === source); setMoveForm({ ...moveForm, source, serial: found?.serial ?? "" }); }} className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200"><option value="">ONU de origem</option>{onus.map((onu) => <option key={onu.id} value={onu.slot}>{onu.slot} · {onu.name}</option>)}</select><select value={moveForm.targetPon} onChange={(e) => setMoveForm({ ...moveForm, targetPon: e.target.value })} className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200"><option value="">PON destino</option>{ponOptions.filter((pon) => pon !== (moveSource?.slot.split(":")[0] ?? "")).map((pon) => <option key={pon} value={pon}>{pon}</option>)}</select><div className="flex h-10 items-center rounded-lg border border-fuchsia-300/20 bg-fuchsia-300/[.06] px-3 text-xs text-fuchsia-100">Vaga automática: {moveAvailability.isLoading ? "consultando..." : moveAvailability.data?.nextOnuId ?? "sem vaga"}</div><input value={moveForm.serial} onChange={(e) => setMoveForm({ ...moveForm, serial: e.target.value })} placeholder="SN da ONU" className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200" /></div><button onClick={moveSelected} disabled={moveOnu.isPending} className="mt-5 inline-flex items-center gap-2 rounded-lg bg-orange-300 px-4 py-2.5 text-xs font-bold text-slate-950 disabled:opacity-50"><MoveRight className="h-4 w-4" />{moveOnu.isPending ? "Movendo..." : "Mover ONU"}</button></section>}

            {activeNav === "Tempo real" && <section className="mb-7 rounded-2xl border border-rose-300/20 bg-[#0b1a2a]/90 p-6"><div className="flex items-center gap-2"><span className="h-2.5 w-2.5 animate-ping rounded-full bg-rose-400" /><p className="text-xs font-semibold uppercase tracking-[.15em] text-rose-300">Tempo real</p></div><h2 className="mt-2 text-xl font-semibold text-white">Desconexões de fibra</h2><p className="mt-1 text-xs text-slate-500">Atualização automática a cada 5 segundos; eventos novos aparecem no topo.</p><div className="mt-5 space-y-2">{(realtimeEvents.length ? realtimeEvents : events.filter((item) => item.type === "fiber")).map((event) => <div key={event.id} className="flex items-center gap-3 rounded-lg border border-rose-400/15 bg-rose-400/[.04] p-3"><span className="h-2.5 w-2.5 animate-pulse rounded-full bg-rose-400" /><div><p className="text-xs font-semibold text-slate-200">{event.title}</p><p className="text-[11px] text-slate-500">{event.detail} · {event.time}</p></div></div>)}</div></section>}

            

            {activeNav === "Logs de operação" && <section className="mb-7 rounded-2xl border border-slate-700 bg-[#0b1a2a]/90 p-6"><p className="text-xs font-semibold uppercase tracking-[.15em] text-slate-400">Logs de operação</p><h2 className="mt-2 text-xl font-semibold text-white">Comandos enviados à OLT</h2><p className="mt-1 text-xs text-slate-500">Registro persistido no banco: operador, data/hora e comandos enviados à OLT.</p><div className="mt-5 space-y-2">{operationLogs.length === 0 && <p className="rounded-lg border border-slate-800 p-4 text-xs text-slate-500">Nenhum comando executado ainda.</p>}{operationLogs.map((log) => <div key={log.id} className="flex items-center justify-between rounded-lg border border-slate-800 bg-slate-950/40 p-3 text-xs"><div><span className="font-semibold text-slate-200">{log.action}</span><span className="ml-3 font-mono text-slate-400">{log.onu}</span><pre className="mt-1 whitespace-pre-wrap text-[10px] text-slate-500">{(log.commands ?? []).join("\n")}</pre></div><div className="text-right text-[10px] text-slate-600"><p>{log.operatorName ?? "operador"}</p><p>{new Intl.DateTimeFormat("pt-BR", { dateStyle: "short", timeStyle: "medium", timeZone: "America/Sao_Paulo" }).format(new Date(log.createdAt ?? Date.now()))}</p></div></div>)}</div></section>}

            {activeNav === "Users" && <section className="mb-7 rounded-2xl border border-fuchsia-300/20 bg-[#0b1a2a]/90 p-6"><p className="text-xs font-semibold uppercase tracking-[.15em] text-fuchsia-300">Users</p><h2 className="mt-2 text-xl font-semibold text-white">Usuários e permissões · versão 1.0</h2><p className="mt-1 text-xs text-slate-500">Cadastro persistido no banco. As senhas são armazenadas somente como hash e nunca retornadas à interface.</p><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><input value={newOperator.name} onChange={(e) => setNewOperator({ ...newOperator, name: e.target.value })} placeholder="Nome" className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200" /><input value={newOperator.email} onChange={(e) => setNewOperator({ ...newOperator, email: e.target.value })} placeholder="E-mail" className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200" /><input value={newOperator.username} onChange={(e) => setNewOperator({ ...newOperator, username: e.target.value })} placeholder="Usuário / login" className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200" /><input type="password" value={newOperator.password} onChange={(e) => setNewOperator({ ...newOperator, password: e.target.value })} placeholder="Senha" className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200" /><select value={newOperator.role} onChange={(e) => setNewOperator({ ...newOperator, role: e.target.value })} className="h-10 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200"><option value="tecnico">Técnico · Tempo real</option><option value="operador">Operador · Operações</option><option value="admin">Administrador · Tudo</option></select></div><button onClick={() => { if (!newOperator.name.trim() || !newOperator.username.trim() || (!newOperator.password.trim() && editingUserIndex === null)) { toast.warning("Informe nome, usuário e senha"); return; } const current = editingUserIndex === null ? null : operatorUsers[editingUserIndex]; operatorSave.mutate({ id: current?.id, name: newOperator.name.trim(), email: newOperator.email.trim(), username: newOperator.username.trim(), password: newOperator.password.trim() || undefined, role: newOperator.role as "tecnico" | "operador" | "admin" }, { onSuccess: () => { setNewOperator({ name: "", email: "", username: "", password: "", role: "tecnico" }); setEditingUserIndex(null); toast.success(editingUserIndex === null ? "Usuário cadastrado no banco" : "Usuário atualizado no banco"); }, onError: (error) => toast.error("Falha ao salvar usuário", { description: error.message }) }); }} className="mt-4 rounded-lg bg-fuchsia-300 px-4 py-2.5 text-xs font-bold text-slate-950">{editingUserIndex === null ? "Cadastrar usuário" : "Salvar usuário"}</button><div className="mt-5 space-y-2">{operatorUsers.map((user, index) => <div key={`${user.username || user.email}-${index}`} className="flex items-center justify-between rounded-lg border border-slate-800 bg-slate-950/40 p-3 text-xs"><div><p className="font-semibold text-slate-200">{user.name}</p><p className="text-slate-500">{user.username || user.email} · {user.role} · senha cadastrada</p></div><div className="flex gap-3"><button onClick={() => { setEditingUserIndex(index); setNewOperator({ name: user.name, email: user.email || "", username: user.username || user.email || "", password: "", role: user.role }); }} className="text-fuchsia-300">Editar</button><button onClick={() => { if (!window.confirm(`Remover o usuário ${user.username}?`)) return; operatorRemove.mutate({ id: user.id }, { onSuccess: () => toast.success("Usuário removido do banco"), onError: (error) => toast.error("Falha ao remover usuário", { description: error.message }) }); }} className="text-rose-300">Remover</button></div></div>)}</div></section>}
            {activeNav === "Terminal" && <section className="mb-7 rounded-2xl border border-fuchsia-300/20 bg-[#0b1a2a]/90 p-6"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-semibold uppercase tracking-[.15em] text-fuchsia-300">Terminal ZTE C300</p><h2 className="mt-2 text-xl font-semibold text-white">Console Telnet operacional</h2><p className="mt-1 text-xs text-slate-500">Executa comandos diretamente na OLT configurada. Para alterações, informe primeiro <code>configure terminal</code>.</p></div><span className="rounded-full border border-emerald-400/20 bg-emerald-400/10 px-2 py-1 text-[10px] text-emerald-200">TCP Telnet</span></div><div className="mt-5 flex flex-col gap-3 sm:flex-row"><textarea value={terminalCommand} onChange={(e) => setTerminalCommand(e.target.value)} placeholder="Digite ou cole comandos ZTE; uma linha por comando..." rows={3} className="min-h-11 min-w-0 flex-1 resize-y rounded-lg border border-fuchsia-300/20 bg-slate-950/80 px-3 py-2 font-mono text-xs text-slate-100 outline-none focus:border-fuchsia-300/60" /><button onClick={() => { if (!terminalCommand.trim() || terminalMutation.isPending) return; terminalMutation.mutate({ command: terminalCommand.trim() }, { onSuccess: (result) => { setTerminalHistory((current) => [{ command: result.command, output: result.output, time: new Date().toLocaleTimeString("pt-BR", { timeZone: "America/Sao_Paulo" }) }, ...current].slice(0, 40)); logCreate.mutate({ action: "terminal", commands: result.command.split(/\r?\n/).filter(Boolean) }); }, onError: (error) => toast.error("Falha no terminal", { description: error.message }) }); }} disabled={terminalMutation.isPending || !terminalCommand.trim()} className="inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-fuchsia-300 px-5 text-xs font-bold text-slate-950 disabled:opacity-50"><Terminal className="h-4 w-4" />{terminalMutation.isPending ? "Executando..." : "Executar"}</button></div><div className="mt-3 flex flex-wrap gap-2">{["show version", "show gpon onu state", "show card", "show running-config", "configure terminal"].map((command) => <button key={command} onClick={() => setTerminalCommand(command)} className="rounded-md border border-slate-700 px-2.5 py-1.5 font-mono text-[10px] text-slate-400 hover:border-fuchsia-300/40 hover:text-fuchsia-200">{command}</button>)}</div><div className="mt-5 max-h-[520px] space-y-3 overflow-auto rounded-xl border border-slate-800 bg-[#02070d] p-4">{terminalHistory.length === 0 && <p className="font-mono text-xs text-slate-600">Nenhum comando executado nesta sessão.</p>}{terminalHistory.map((item, index) => <div key={`${item.time}-${index}`} className="border-b border-slate-900 pb-3 last:border-0"><p className="font-mono text-xs text-fuchsia-300">CHAPARRAL-C300# {item.command} <span className="ml-2 text-[10px] text-slate-600">{item.time}</span></p><pre className="mt-2 whitespace-pre-wrap font-mono text-[11px] leading-relaxed text-slate-300">{item.output || "(sem resposta)"}</pre></div>)}</div></section>}
            {activeNav === "Interfaces / VLANs" && <section className="mb-7 rounded-2xl border border-orange-300/20 bg-[#0b1a2a]/90 p-6"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[.15em] text-orange-300">Interfaces / VLANs / IPs</p><h2 className="mt-2 text-xl font-semibold text-white">Dados coletados da OLT</h2><p className="mt-1 text-xs text-slate-500">Origem: <code>show running-config</code> via Telnet na ZTE C300. Resultado mantido em cache por 5 minutos.</p></div><button onClick={() => networkConfig.refetch()} className="inline-flex items-center gap-2 rounded-lg border border-orange-300/30 px-3 py-2 text-xs font-semibold text-orange-200"><RefreshCw className={`h-3.5 w-3.5 ${networkConfig.isFetching ? "animate-spin" : ""}`} />Atualizar</button></div><div className="mt-5 overflow-hidden rounded-xl border border-slate-800"><div className="grid grid-cols-3 gap-3 border-b border-slate-800 bg-slate-950/60 px-4 py-3 text-[10px] font-semibold uppercase tracking-wider text-slate-500"><span>Interface</span><span>VLAN</span><span>IP</span></div>{networkConfig.isLoading && <p className="p-5 text-xs text-slate-500">Consultando a configuração real da OLT...</p>}{networkConfig.isError && <p className="p-5 text-xs text-rose-300">Não foi possível ler as interfaces da OLT. Verifique o Telnet e tente atualizar.</p>}{!networkConfig.isLoading && !networkConfig.isError && (networkConfig.data ?? []).length === 0 && <p className="p-5 text-xs text-slate-500">A OLT não retornou interfaces/VLANs/IPs no comando show running-config.</p>}{(networkConfig.data ?? []).map((entry, index) => <div key={`${entry.interfaceName}-${entry.vlan}-${index}`} className="grid grid-cols-3 gap-3 border-b border-slate-900 px-4 py-3 text-xs last:border-0"><span className="font-mono text-orange-200">{entry.interfaceName}</span><span className="font-mono text-slate-300">{entry.vlan || "—"}</span><span className="font-mono text-fuchsia-200">{entry.ip || "—"}</span></div>)}</div></section>}
            {activeNav === "Configurações" && <section className="mb-7 rounded-2xl border border-fuchsia-300/20 bg-[#0b1a2a]/90 p-6 shadow-[0_12px_32px_rgba(0,0,0,.18)]"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[.15em] text-fuchsia-300">Configurações da OLT</p><h2 className="mt-2 text-xl font-semibold text-white">Parâmetros reais da conexão</h2><p className="mt-1 text-xs text-slate-500">Os valores abaixo foram lidos do ambiente protegido e podem ser ajustados para a próxima sincronização.</p></div><span className="rounded-full border border-emerald-400/20 bg-emerald-400/10 px-2.5 py-1 text-[10px] font-semibold text-emerald-200">{oltConfig.data?.communityConfigured ? "SNMP configurado" : "SNMP pendente"}</span></div><div className="mt-5 flex flex-wrap items-center gap-3 rounded-lg border border-fuchsia-300/15 bg-fuchsia-300/[.04] p-3"><span className="text-xs text-slate-400">Logo da empresa</span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={(e) => { const file = e.target.files?.[0]; if (!file) return; const reader = new FileReader(); reader.onload = () => { const value = String(reader.result); setLogoSrc(value); localStorage.setItem("olt-logo", value); toast.success("Logo atualizado"); }; reader.readAsDataURL(file); }} className="max-w-full text-xs text-slate-400" /><button onClick={() => { setLogoSrc("/logo-xtremnet.png"); localStorage.removeItem("olt-logo"); }} className="rounded-lg border border-slate-700 px-3 py-2 text-xs text-slate-300">Restaurar XtremNet</button></div><div className="mt-5 flex flex-wrap items-center gap-3 rounded-lg border border-slate-800 bg-slate-950/30 p-3"><select onChange={(e) => { const profile = oltProfiles.find((item) => item.name === e.target.value); if (profile) setConfigForm((current) => ({ ...current, host: profile.host, snmpPort: profile.snmpPort, telnetPort: profile.telnetPort, boards: profile.boards })); }} className="h-9 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200"><option value="">Perfis de OLT salvos</option>{oltProfiles.map((profile) => <option key={profile.name} value={profile.name}>{profile.name} · {profile.host}</option>)}</select><input value={oltProfileName} onChange={(e) => setOltProfileName(e.target.value)} placeholder="Nome da nova OLT" className="h-9 rounded-lg border border-slate-700 bg-slate-950/60 px-3 text-xs text-slate-200" /><button onClick={() => { if (!oltProfileName.trim() || !configForm.host) { toast.warning("Informe nome e host da OLT"); return; } const next = [...oltProfiles.filter((item) => item.name !== oltProfileName.trim()), { name: oltProfileName.trim(), ...configForm }]; setOltProfiles(next); localStorage.setItem("olt-profiles", JSON.stringify(next)); setOltProfileName(""); toast.success("Perfil de OLT salvo"); }} className="rounded-lg border border-fuchsia-300/30 px-3 py-2 text-xs font-semibold text-fuchsia-200">Salvar perfil</button></div><div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><label className="text-xs text-slate-400">Host/IP<input value={configForm.host} onChange={(e) => setConfigForm({ ...configForm, host: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-slate-700 bg-slate-950/60 px-3 font-mono text-xs text-slate-200 outline-none focus:border-fuchsia-300/50" /></label><label className="text-xs text-slate-400">Porta SNMP<input inputMode="numeric" value={configForm.snmpPort} onChange={(e) => setConfigForm({ ...configForm, snmpPort: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-slate-700 bg-slate-950/60 px-3 font-mono text-xs text-slate-200 outline-none focus:border-fuchsia-300/50" /></label><label className="text-xs text-slate-400">Porta Telnet<input inputMode="numeric" value={configForm.telnetPort} onChange={(e) => setConfigForm({ ...configForm, telnetPort: e.target.value })} className="mt-2 h-10 w-full rounded-lg border border-slate-700 bg-slate-950/60 px-3 font-mono text-xs text-slate-200 outline-none focus:border-fuchsia-300/50" /></label><label className="text-xs text-slate-400">Slots:PONs<input value={configForm.boards} onChange={(e) => setConfigForm({ ...configForm, boards: e.target.value })} placeholder="8:8,9:16" className="mt-2 h-10 w-full rounded-lg border border-slate-700 bg-slate-950/60 px-3 font-mono text-xs text-slate-200 outline-none focus:border-fuchsia-300/50" /></label><label className="text-xs text-slate-400">Usuário Telnet<input value={configForm.telnetUsername} onChange={(e) => setConfigForm({ ...configForm, telnetUsername: e.target.value })} placeholder={oltConfig.data?.usernameConfigured ? "Configurado · manter atual" : "Usuário da OLT"} autoComplete="off" className="mt-2 h-10 w-full rounded-lg border border-slate-700 bg-slate-950/60 px-3 font-mono text-xs text-slate-200 outline-none focus:border-fuchsia-300/50" /></label><label className="text-xs text-slate-400">Senha Telnet<input type="password" value={configForm.telnetPassword} onChange={(e) => setConfigForm({ ...configForm, telnetPassword: e.target.value })} placeholder={oltConfig.data?.usernameConfigured ? "Configurada · manter atual" : "Senha da OLT"} autoComplete="new-password" className="mt-2 h-10 w-full rounded-lg border border-slate-700 bg-slate-950/60 px-3 font-mono text-xs text-slate-200 outline-none focus:border-fuchsia-300/50" /></label></div><div className="mt-5 flex flex-wrap items-center justify-between gap-3"><p className="text-[11px] text-slate-500">Credenciais: {oltConfig.data?.usernameConfigured ? "configuradas e ocultas" : "não configuradas"}. Nunca são exibidas na tela.</p><button onClick={saveConfig} disabled={configUpdate.isPending} className="rounded-lg bg-fuchsia-300 px-4 py-2.5 text-xs font-bold text-slate-950 transition hover:bg-fuchsia-200 disabled:opacity-50">{configUpdate.isPending ? "Salvando..." : "Salvar configuração"}</button></div></section>}

            <section className="mb-7 flex flex-col justify-between gap-4 md:flex-row md:items-end"><div><p className="text-sm text-slate-500">{new Intl.DateTimeFormat("pt-BR", { dateStyle: "full", timeStyle: "short", timeZone: "America/Sao_Paulo" }).format(new Date())}</p><h2 className="mt-2 text-3xl font-semibold tracking-tight text-white">Olá, {user?.name || "operador"}<span className="text-fuchsia-300">.</span></h2><p className="mt-1 text-sm text-slate-400">Acompanhe sua rede de fibra e responda rápido aos eventos críticos.</p>{liveSnapshot.isLoading && <p className="mt-3 text-xs text-fuchsia-200">Consultando dados reais da OLT C300...</p>}{liveSnapshot.error && <p className="mt-3 rounded-lg border border-rose-400/20 bg-rose-400/10 px-3 py-2 text-xs text-rose-200">Falha na coleta real: {liveSnapshot.error.message}</p>}</div><button onClick={() => { liveSnapshot.refetch().then(() => toast.success("Eventos e estados atualizados")); }} className="inline-flex items-center justify-center gap-2 rounded-lg bg-fuchsia-300 px-4 py-2.5 text-xs font-bold text-slate-950 shadow-[0_0_22px_rgba(103,232,249,.12)] transition hover:bg-fuchsia-200 active:scale-[.98]"><Zap className="h-4 w-4" />Atualizar telemetria</button></section>

            <section className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div onClick={() => focusTable("todos")} role="button" tabIndex={0} className="cursor-pointer rounded-2xl border border-slate-800/80 bg-[#0b1a2a]/75 p-5 shadow-[0_12px_32px_rgba(0,0,0,.12)] transition hover:-translate-y-0.5 hover:border-fuchsia-300/30"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-slate-500">Total de ONUs</p><p className="mt-2 text-3xl font-semibold tracking-tight text-white">{onus.length}<span className="ml-2 text-sm font-normal text-slate-500">unidades</span></p></div><div className="rounded-xl bg-blue-400/10 p-2.5 text-blue-300"><Network className="h-5 w-5" /></div></div><div className="mt-4 flex items-center gap-2 text-[11px] text-slate-500"><ArrowUpRight className="h-3.5 w-3.5 text-emerald-300" /><span className="text-emerald-300">2,4%</span> vs. mês anterior</div></div><div onClick={() => focusTable("online")} role="button" tabIndex={0} className="cursor-pointer rounded-2xl border border-slate-800/80 bg-[#0b1a2a]/75 p-5 shadow-[0_12px_32px_rgba(0,0,0,.12)] transition hover:-translate-y-0.5 hover:border-fuchsia-300/30"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-slate-500">Online agora</p><p className="mt-2 text-3xl font-semibold tracking-tight text-emerald-300">{onlineCount}<span className="ml-2 text-sm font-normal text-slate-500">{onus.length ? Math.round((onlineCount / onus.length) * 100) : 0}%</span></p></div><div className="rounded-xl bg-emerald-400/10 p-2.5 text-emerald-300"><Wifi className="h-5 w-5" /></div></div><div className="mt-4 h-1.5 overflow-hidden rounded-full bg-slate-800"><div className="h-full rounded-full bg-emerald-400" style={{ width: `${onus.length ? (onlineCount / onus.length) * 100 : 0}%` }} /></div></div><div onClick={() => focusTable("alerta")} role="button" tabIndex={0} className="cursor-pointer rounded-2xl border border-slate-800/80 bg-[#0b1a2a]/75 p-5 shadow-[0_12px_32px_rgba(0,0,0,.12)] transition hover:-translate-y-0.5 hover:border-fuchsia-300/30"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-slate-500">Em alerta</p><p className="mt-2 text-3xl font-semibold tracking-tight text-amber-200">{alertCount}<span className="ml-2 text-sm font-normal text-slate-500">atenção</span></p></div><div className="rounded-xl bg-amber-300/10 p-2.5 text-amber-200"><AlertTriangle className="h-5 w-5" /></div></div><div className="mt-4 flex items-center gap-2 text-[11px] text-slate-500"><span className="h-1.5 w-1.5 rounded-full bg-amber-300" />Potência óptica fora do ideal</div></div><div onClick={() => focusTable("offline")} role="button" tabIndex={0} className="cursor-pointer rounded-2xl border border-rose-400/20 bg-rose-400/[.06] p-5 shadow-[0_12px_32px_rgba(0,0,0,.12)] transition hover:-translate-y-0.5 hover:border-rose-300/40"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-rose-200/70">Desconectadas</p><p className="mt-2 text-3xl font-semibold tracking-tight text-rose-300">{offlineCount}<span className="ml-2 text-sm font-normal text-rose-200/50">fibra</span></p></div><div className="rounded-xl bg-rose-400/10 p-2.5 text-rose-300"><CircleOff className="h-5 w-5" /></div></div><div className="mt-4 flex items-center gap-2 text-[11px] text-rose-200/70"><ArrowDownRight className="h-3.5 w-3.5" />3 eventos nos últimos 60 min</div></div><div onClick={() => setStatusFilter("offline")} role="button" tabIndex={0} className="cursor-pointer rounded-2xl border border-amber-300/20 bg-amber-300/[.06] p-5 shadow-[0_12px_32px_rgba(0,0,0,.12)] transition hover:border-amber-200/40"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-amber-200/70">Sem energia</p><p className="mt-2 text-3xl font-semibold tracking-tight text-amber-200">{onus.filter((onu) => onu.lastEvent === "Sem energia (Dying Gasp)").length}<span className="ml-2 text-sm font-normal text-amber-200/50">ONUs</span></p></div><div className="rounded-xl bg-amber-300/10 p-2.5 text-amber-200"><PlugZap className="h-5 w-5" /></div></div><div className="mt-4 text-[11px] text-amber-200/70">Status coletado da OLT</div></div></section>

            {selected && <section className="mb-6 rounded-2xl border border-fuchsia-300/20 bg-gradient-to-br from-[#10283a] to-[#0b1a2a] p-5 shadow-[0_12px_32px_rgba(0,0,0,.16)]"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div><p className="text-[10px] font-semibold uppercase tracking-[.15em] text-fuchsia-300">Histórico individual da ONU</p><h3 className="mt-1 text-lg font-semibold text-white">{selected.name}</h3><p className="mt-1 font-mono text-[11px] text-slate-500">{selected.slot} · {selected.serial} · {selected.mac}</p></div><button onClick={() => setSelectedId(null)} className="self-start rounded-lg border border-slate-700 px-3 py-1.5 text-[11px] text-slate-400 hover:border-fuchsia-300/40 hover:text-fuchsia-200">Fechar painel</button></div><div className="mt-5 grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><div className="rounded-lg bg-slate-950/40 p-3"><p className="text-[9px] uppercase tracking-wider text-slate-600">Estado atual</p><div className="mt-1"><Badge status={selected.status} /></div></div><div className="rounded-lg bg-slate-950/40 p-3"><p className="text-[9px] uppercase tracking-wider text-slate-600">Sinal RX atual</p><p className="mt-1 font-mono text-sm text-slate-200">{selected.signal <= -90 ? "Sem sinal" : `${selected.signal.toFixed(1)} dBm`}</p></div><div className="rounded-lg bg-slate-950/40 p-3"><p className="text-[9px] uppercase tracking-wider text-slate-600">Distância</p><p className="mt-1 font-mono text-sm text-slate-200">{formatDistance(selected.distance)}</p></div><div className="rounded-lg bg-slate-950/40 p-3"><p className="text-[9px] uppercase tracking-wider text-slate-600">Tempo online</p><p className="mt-1 font-mono text-sm text-slate-200">{selected.uptime}</p></div><div className="rounded-lg bg-slate-950/40 p-3"><p className="text-[9px] uppercase tracking-wider text-slate-600">Último evento</p><p className="mt-1 truncate text-xs text-slate-200">{selected.lastEvent}</p></div></div><div className="mt-5 grid gap-4 lg:grid-cols-[minmax(0,1fr)_320px]"><div className="rounded-xl border border-slate-800 bg-slate-950/35 p-4"><div className="flex items-center justify-between"><div><p className="text-xs font-semibold text-slate-200">Histórico de sinal RX</p><p className="mt-1 text-[10px] text-slate-500">Últimas {selectedHistory.length} alterações coletadas neste navegador</p></div><span className="font-mono text-[10px] text-slate-500">{historySignals.length ? `${minHistorySignal.toFixed(1)} a ${maxHistorySignal.toFixed(1)} dBm` : "aguardando leituras"}</span></div>{historySignals.length > 1 ? <div className="mt-4 flex h-28 items-end gap-1 overflow-hidden border-b border-slate-800 px-1">{historySignals.slice(-48).map((point, index) => { const height = Math.max(8, Math.min(100, ((point.signal + 35) / 25) * 100)); return <div key={`${point.at}-${index}`} title={`${new Date(point.at).toLocaleTimeString("pt-BR", { timeZone: "America/Sao_Paulo" })} · ${point.signal.toFixed(1)} dBm`} className={`min-w-1 flex-1 rounded-t ${point.signal < -27 ? "bg-amber-300" : "bg-fuchsia-300"}`} style={{ height: `${height}%` }} />; })}</div> : <div className="mt-4 flex h-28 items-center justify-center rounded-lg border border-dashed border-slate-800 text-xs text-slate-600">O gráfico será preenchido conforme novas leituras chegarem.</div>}</div><div className="rounded-xl border border-slate-800 bg-slate-950/35 p-4"><p className="text-xs font-semibold text-slate-200">Linha do tempo</p><div className="mt-3 max-h-36 space-y-2 overflow-auto">{selectedHistory.slice(-8).reverse().map((point, index) => <div key={`${point.at}-${index}`} className="flex items-center justify-between gap-3 text-[10px]"><span className={point.status === "offline" ? "text-rose-300" : point.status === "alerta" ? "text-amber-200" : "text-emerald-300"}>{point.event}</span><span className="shrink-0 font-mono text-slate-600">{new Date(point.at).toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short", timeZone: "America/Sao_Paulo" })}</span></div>)}{selectedHistory.length === 0 && <p className="text-[11px] text-slate-600">Nenhuma leitura histórica ainda.</p>}</div><p className="mt-3 text-[10px] text-slate-600">Operações relacionadas: {selectedLogs.length}. O histórico de comandos fica disponível no menu Logs de operação.</p></div></div></section>}

            <section ref={tableRef} className="mt-6 grid gap-5 xl:grid-cols-[minmax(0,1fr)_360px]"><div className="min-w-0 rounded-2xl border border-slate-800/80 bg-[#0b1a2a]/75 shadow-[0_12px_32px_rgba(0,0,0,.12)]"><div className="flex flex-col justify-between gap-4 border-b border-slate-800/80 p-5 sm:flex-row sm:items-center"><div><div className="flex items-center gap-2"><span className="relative flex h-2 w-2"><span className="absolute h-full w-full animate-ping rounded-full bg-fuchsia-300" /><span className="relative h-2 w-2 rounded-full bg-fuchsia-300" /></span><h3 className="text-sm font-semibold text-white">ONUs monitoradas</h3></div><p className="mt-1 text-xs text-slate-500">Estado da rede em tempo quase real</p></div><div className="flex flex-wrap items-center gap-2"><div className="relative min-w-[220px] flex-1"><Search className="absolute left-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-slate-600" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar por nome, MAC ou serial..." aria-label="Buscar ONU por nome, MAC ou serial" className="h-9 w-full rounded-lg border border-slate-700 bg-slate-900/70 pl-9 pr-3 text-xs text-slate-200 outline-none transition placeholder:text-slate-600 focus:border-fuchsia-300/50 sm:w-[245px]" /></div><div className="relative"><Settings2 className="pointer-events-none absolute left-3 top-1/2 h-3.5 w-3.5 -translate-y-1/2 text-fuchsia-300/70" /><select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value as "todos" | ONUStatus)} aria-label="Filtrar ONUs por status" className="h-9 appearance-none rounded-lg border border-slate-700 bg-slate-900/70 pl-9 pr-8 text-xs text-slate-300 outline-none transition hover:border-fuchsia-300/40 focus:border-fuchsia-300/50"><option value="todos">Todos os status</option><option value="online">Online</option><option value="alerta">Alerta</option><option value="offline">Offline</option></select><select value={ponFilter} onChange={(event) => setPonFilter(event.target.value)} aria-label="Filtrar por slot PON" className="h-9 rounded-lg border border-slate-700 bg-slate-900/70 px-3 text-xs text-slate-300 outline-none transition hover:border-fuchsia-300/40 focus:border-fuchsia-300/50"><option value="todos">Todos os slots PON</option>{ponOptions.map((pon) => <option key={pon} value={pon}>{pon}</option>)}</select><ChevronRight className="pointer-events-none absolute right-2.5 top-1/2 h-3.5 w-3.5 -translate-y-1/2 rotate-90 text-slate-600" /></div>{(search || statusFilter !== "todos" || ponFilter !== "todos") && <button onClick={() => { setSearch(""); setStatusFilter("todos"); setPonFilter("todos"); }} className="inline-flex h-9 items-center gap-1.5 rounded-lg border border-slate-700 bg-slate-900/70 px-3 text-[11px] font-semibold text-slate-400 transition hover:border-rose-400/40 hover:text-rose-200"><X className="h-3.5 w-3.5" />Limpar</button>}</div></div><div className="flex flex-wrap items-center gap-2 border-b border-slate-800/50 px-5 py-3"><span className="text-[10px] uppercase tracking-[.12em] text-slate-600">Filtros rápidos</span>{(["todos", "online", "alerta", "offline"] as const).map((filter) => <button key={filter} onClick={() => setStatusFilter(filter)} className={`rounded-full border px-2.5 py-1 text-[10px] font-semibold transition ${statusFilter === filter ? "border-fuchsia-300/40 bg-fuchsia-300/10 text-fuchsia-200" : "border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300"}`}>{filter === "todos" ? "Todos" : filter === "online" ? "Online" : filter === "alerta" ? "Alertas" : "Offline"}{filter !== "todos" && <span className="ml-1.5 opacity-60">{onus.filter((onu) => onu.status === filter).length}</span>}</button>)}{(search || statusFilter !== "todos" || ponFilter !== "todos") && <span className="ml-auto text-[10px] text-slate-500">{filteredOnus.length} resultado{filteredOnus.length === 1 ? "" : "s"}</span>}</div><div className="hidden overflow-x-auto md:block"><table className="w-full text-left"><thead><tr className="border-b border-slate-800/60 text-[10px] font-semibold uppercase tracking-[.12em] text-slate-600"><th className="px-5 py-3">ONU / cliente</th><th className="px-3 py-3">PON</th><th className="px-3 py-3">Estado</th><th className="px-3 py-3">Sinal RX</th><th className="px-3 py-3">Distância</th><th className="px-5 py-3 text-right">Ações</th></tr></thead><tbody>{filteredOnus.map((onu) => <tr key={onu.id} onClick={() => { setSelectedId(onu.id); toast(`${onu.name}`, { description: `${onu.slot} · ${onu.status} · ${onu.signal <= -90 ? "métrica pendente" : `${onu.signal.toFixed(1)} dBm`}` }); }} className={`cursor-pointer border-b border-slate-800/40 transition hover:bg-fuchsia-300/[.035] ${selectedId === onu.id ? "bg-fuchsia-300/[.06]" : ""}`}><td className="px-5 py-4"><div className="flex items-center gap-3"><div className={`flex h-9 w-9 items-center justify-center rounded-lg ${onu.status === "offline" ? "bg-rose-400/10 text-rose-300" : onu.status === "alerta" ? "bg-amber-300/10 text-amber-200" : "bg-fuchsia-300/10 text-fuchsia-200"}`}><Server className="h-4 w-4" /></div><div>{editingDescriptionId === onu.id ? <div className="flex items-center gap-1"><input autoFocus value={descriptionDraft} onChange={(event) => setDescriptionDraft(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") saveDescription(onu); if (event.key === "Escape") setEditingDescriptionId(null); }} placeholder="Descrição" maxLength={64} className="h-7 w-44 rounded border border-fuchsia-300/40 bg-slate-950/80 px-2 text-xs text-slate-100 outline-none" /><button onClick={() => saveDescription(onu)} disabled={descriptionUpdate.isPending} className="rounded bg-fuchsia-300 px-2 py-1 text-[10px] font-bold text-slate-950">Salvar</button><button onClick={() => setEditingDescriptionId(null)} className="rounded border border-slate-700 px-2 py-1 text-[10px] text-slate-400">Cancelar</button></div> : <div className="group/name flex items-center gap-1"><p className="text-xs font-semibold text-slate-200">{onu.name}</p><button aria-label={`Editar descrição de ${onu.name}`} onClick={(event) => { event.stopPropagation(); startDescriptionEdit(onu); }} className="opacity-70 transition sm:opacity-0 sm:group-hover/name:opacity-100"><Pencil className="h-3 w-3 text-fuchsia-300" /></button></div>}<p className="mt-1 font-mono text-[10px] text-slate-600">{onu.serial} · {onu.mac}</p></div></div></td><td className="px-3 py-4 font-mono text-[11px] text-slate-400">{onu.slot}</td><td className="px-3 py-4"><Badge status={onu.status} /></td><td className="px-3 py-4"><div className="flex items-center gap-2"><SignalBars signal={onu.signal} /><span className={`font-mono text-xs ${onu.signal < -26 ? "text-amber-200" : onu.signal < -30 ? "text-rose-300" : "text-slate-300"}`}>{onu.signal <= -90 ? (onu.status === "offline" ? "Sem sinal" : "Aguardando") : onu.signal.toFixed(1)} {onu.signal > -90 && <span className="text-[10px] text-slate-600">dBm</span>}</span></div></td><td className="px-3 py-4"><span className="font-mono text-xs text-slate-300">{formatDistance(onu.distance)} </span></td><td className="px-5 py-4"><div className="flex justify-end gap-0.5" onClick={(event) => event.stopPropagation()}><ActionButton icon={ShieldCheck} label="Ativar" tone="cyan" onClick={() => runAction("authorize", onu)} /><ActionButton icon={LockKeyhole} label="Desativar" tone="danger" onClick={() => runAction("disable", onu)} /><ActionButton icon={Power} label="Reboot" onClick={() => runAction("reboot", onu)} /><ActionButton icon={MoveRight} label="Mover" onClick={() => { setMoveForm({ source: onu.slot, targetPon: "", targetOnuId: "", serial: onu.serial }); setActiveNav("Mover ONU"); window.scrollTo({ top: 0, behavior: "smooth" }); }} /></div></td></tr>)}</tbody></table></div><div className="space-y-3 p-3 md:hidden">{filteredOnus.map((onu) => <article key={`mobile-${onu.id}`} onClick={() => { setSelectedId(onu.id); }} className={`rounded-xl border p-3 ${selectedId === onu.id ? "border-fuchsia-300/40 bg-fuchsia-300/[.06]" : "border-slate-800 bg-slate-950/30"}`}><div className="flex items-start justify-between gap-3"><div className="min-w-0"><div className="flex items-center gap-2"><div className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-lg ${onu.status === "offline" ? "bg-rose-400/10 text-rose-300" : onu.status === "alerta" ? "bg-amber-300/10 text-amber-200" : "bg-fuchsia-300/10 text-fuchsia-200"}`}><Server className="h-4 w-4" /></div><div className="min-w-0"><p className="truncate text-xs font-semibold text-slate-200">{onu.name}</p><p className="truncate font-mono text-[10px] text-slate-600">{onu.serial} · {onu.mac}</p></div></div></div><Badge status={onu.status} /></div><div className="mt-3 grid grid-cols-2 gap-2 text-[11px]"><div className="rounded-lg bg-slate-900/70 p-2"><p className="text-[9px] uppercase tracking-wide text-slate-600">PON</p><p className="mt-1 font-mono text-slate-300">{onu.slot}</p></div><div className="rounded-lg bg-slate-900/70 p-2"><p className="text-[9px] uppercase tracking-wide text-slate-600">Sinal RX</p><div className="mt-1 flex items-center gap-2"><SignalBars signal={onu.signal} /><span className="font-mono text-slate-300">{onu.signal <= -90 ? "Sem sinal" : `${onu.signal.toFixed(1)} dBm`}</span></div></div><div className="rounded-lg bg-slate-900/70 p-2"><p className="text-[9px] uppercase tracking-wide text-slate-600">Distância</p><p className="mt-1 font-mono text-slate-300">{formatDistance(onu.distance)}</p></div><div className="rounded-lg bg-slate-900/70 p-2"><p className="text-[9px] uppercase tracking-wide text-slate-600">Evento</p><p className="mt-1 truncate text-slate-300">{onu.lastEvent}</p></div></div><div className="mt-3 grid grid-cols-2 gap-2" onClick={(event) => event.stopPropagation()}><ActionButton icon={ShieldCheck} label="Ativar" tone="cyan" onClick={() => runAction("authorize", onu)} /><ActionButton icon={LockKeyhole} label="Desativar" tone="danger" onClick={() => runAction("disable", onu)} /><ActionButton icon={Power} label="Reboot" onClick={() => runAction("reboot", onu)} /><ActionButton icon={MoveRight} label="Mover" onClick={() => { setMoveForm({ source: onu.slot, targetPon: "", targetOnuId: "", serial: onu.serial }); setActiveNav("Mover ONU"); window.scrollTo({ top: 0, behavior: "smooth" }); }} /></div></article>)}</div>{filteredOnus.length === 0 && <div className="p-12 text-center text-sm text-slate-500">Nenhuma ONU encontrada com os filtros atuais.</div>}</div>

              <aside className="space-y-5"><div className="rounded-2xl border border-fuchsia-300/15 bg-gradient-to-br from-[#103047] to-[#0b1a2a] p-5 shadow-[0_12px_32px_rgba(0,0,0,.16)]"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-slate-400">Disponibilidade média</p><p className="mt-2 text-3xl font-semibold tracking-tight text-white">99,84<span className="text-base text-fuchsia-300">%</span></p></div><div className="rounded-xl bg-fuchsia-300/10 p-2.5 text-fuchsia-200"><Gauge className="h-5 w-5" /></div></div><div className="mt-5"><MiniSparkline /><div className="mt-1 flex justify-between text-[10px] text-slate-600"><span>00h</span><span>06h</span><span>12h</span><span>18h</span><span>agora</span></div></div><div className="mt-4 flex items-center gap-2 text-[11px]"><span className="rounded bg-emerald-400/10 px-1.5 py-0.5 font-semibold text-emerald-300">+0,12%</span><span className="text-slate-500">nas últimas 24h</span></div></div>
                <div className="rounded-2xl border border-slate-800/80 bg-[#0b1a2a]/75 p-5"><div className="flex items-center justify-between"><div><h3 className="text-sm font-semibold text-white">Eventos recentes</h3><p className="mt-1 text-xs text-slate-500">Feed de fibra e operação</p></div><button onClick={() => navigate("Eventos de fibra")} className="text-[11px] font-semibold text-fuchsia-300 hover:text-fuchsia-200">Ver todos <ChevronRight className="ml-0.5 inline h-3 w-3" /></button></div><div className="mt-5 space-y-4">{(realtimeEvents.length ? realtimeEvents : events).map((event) => <div key={event.id} className={`flex gap-3 ${event.fresh ? "animate-[fadeIn_.25s_ease-out]" : ""}`}><div className={`mt-0.5 flex h-7 w-7 shrink-0 items-center justify-center rounded-lg ${event.type === "fiber" ? "bg-rose-400/10 text-rose-300" : event.type === "warning" ? "bg-amber-300/10 text-amber-200" : "bg-blue-400/10 text-blue-300"}`}>{event.type === "fiber" ? <Cable className="h-3.5 w-3.5" /> : event.type === "warning" ? <AlertTriangle className="h-3.5 w-3.5" /> : <Power className="h-3.5 w-3.5" />}</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-medium text-slate-200">{event.title}</p><p className="mt-1 truncate text-[10px] text-slate-500">{event.detail}</p><p className="mt-1.5 text-[10px] text-slate-600">{event.time}</p></div></div>)}</div></div>
                <div className="rounded-2xl border border-slate-800/80 bg-[#0b1a2a]/75 p-5"><div className="flex items-center gap-2"><CheckCircle2 className="h-4 w-4 text-emerald-300" /><h3 className="text-sm font-semibold text-white">Diagnóstico rápido</h3></div><div className="mt-4 space-y-2 text-xs"><div className="flex items-center justify-between"><span className="text-slate-500">CPU da OLT</span><span className="font-mono text-slate-300">24%</span></div><div className="h-1.5 rounded-full bg-slate-800"><div className="h-full w-[24%] rounded-full bg-fuchsia-300" /></div><div className="flex items-center justify-between pt-2"><span className="text-slate-500">Temperatura</span><span className="font-mono text-slate-300">38,2 °C</span></div><div className="flex items-center justify-between pt-2"><span className="text-slate-500">PONs ativas</span><span className="font-mono text-emerald-300">4 / 4</span></div></div><button onClick={() => toast.success("Diagnóstico concluído", { description: "Nenhuma anomalia adicional encontrada." })} className="mt-4 flex w-full items-center justify-center gap-2 rounded-lg border border-slate-700 py-2 text-[11px] font-semibold text-slate-300 transition hover:border-fuchsia-300/30 hover:bg-fuchsia-300/5 hover:text-fuchsia-100"><Terminal className="h-3.5 w-3.5" />Executar diagnóstico</button></div>
              </aside>
            </section>

            <section className="mt-6 grid gap-4 md:grid-cols-3"><div className="rounded-2xl border border-slate-800/80 bg-[#0b1a2a]/75 p-5"><div className="flex items-center gap-3"><div className="rounded-lg bg-blue-400/10 p-2 text-blue-300"><Cloud className="h-4 w-4" /></div><div><p className="text-xs text-slate-500">RX médio</p><p className="mt-1 font-mono text-lg font-semibold text-white">-22,7 <span className="text-xs font-normal text-slate-500">dBm</span></p></div></div><p className="mt-3 text-[10px] text-slate-600">Média das ONUs online</p></div><div className="rounded-2xl border border-slate-800/80 bg-[#0b1a2a]/75 p-5"><div className="flex items-center gap-3"><div className="rounded-lg bg-violet-400/10 p-2 text-violet-300"><Cable className="h-4 w-4" /></div><div><p className="text-xs text-slate-500">Fibra monitorada</p><p className="mt-1 font-mono text-lg font-semibold text-white">18,42 <span className="text-xs font-normal text-slate-500">km</span></p></div></div><p className="mt-3 text-[10px] text-slate-600">Maior distância: ONU 1/1/1:4</p></div><div className="rounded-2xl border border-slate-800/80 bg-[#0b1a2a]/75 p-5"><div className="flex items-center gap-3"><div className="rounded-lg bg-emerald-400/10 p-2 text-emerald-300"><ShieldCheck className="h-4 w-4" /></div><div><p className="text-xs text-slate-500">Proteção operacional</p><p className="mt-1 text-lg font-semibold text-white">Ativa</p></div></div><p className="mt-3 text-[10px] text-slate-600">Ações críticas registradas em log</p></div></section>
            <footer className="mt-8 flex flex-col justify-between gap-2 border-t border-slate-800/60 pt-5 text-[10px] text-slate-600 sm:flex-row"><span>OLT.OPS · Console operacional ZTE</span><span className="flex items-center gap-2"><span className={`h-1.5 w-1.5 rounded-full ${liveSnapshot.isError ? "bg-rose-400" : "bg-emerald-400"}`} />{liveSnapshot.isError ? "Falha na telemetria real · usando último estado" : "Telemetria real · atualização automática a cada 5s"}</span></footer>
          </div>
        </main>
      </div>
    </div>
  );
}
